    for r, row in enumerate(demo2_out):
        for c, val in enumerate(row):
            if val == color:
                if r not in cols_by_row:
                    cols_by_row[r] = set()
                cols_by_row[r].add(c)

    for r in sorted(cols_by_row.keys()):
        cols_list = sorted(cols_by_row[r])
        print(f"  Color {color} row {r}: cols {cols_list}")

# Also get all columns per color combined
print("\nAll columns per color:")
for color in [1, 3, 6, 8]:
    all_cols = sorted(set(c for r, row in enumerate(demo2_out) for c in range(len(row)) if row[c] == color))
    print(f"  Color {color}: all cols {all_cols}")

# Check first appearance order of each color
demo2_in = [[int(x) for x in line.split()] for line in demo2_in_str.splitlines()]

color_first = {}
for r, row in enumerate(demo2_in):
    for c, val in enumerate(row):
        if val > 0 and val not in color_first:
            color_first[val] = (r, c)

print("Colors in order of first appearance:")
sorted_colors = sorted(color_first.items(), key=lambda x: x[1])
